#include <stdio.h>
#include <stdlib.h>

#define MAXV 8
static int adj[MAXV][MAXV];
static int colour[MAXV];
static int found_cycle;

static void dfs(int u) {
    colour[u] = 1;
    for (int v = 0; v < MAXV; ++v) {
        if (!adj[u][v]) continue;
        if (colour[v] == 0) {
            dfs(v);
            if (found_cycle) return;
        } else if (colour[v] == 1) {
            found_cycle = 1;
            return;
        }
    }
    colour[u] = 2;
}

int main(int argc, char *argv[]) {
    if ((argc - 1) & 1) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (int i = 0; i < MAXV; ++i) {
        colour[i] = 0;
        for (int j = 0; j < MAXV; ++j) adj[i][j] = 0;
    }
    found_cycle = 0;
    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long u = strtol(argv[i], &endptr, 10);
        long v = strtol(argv[i+1], &endptr, 10);
        if (u < 0 || u >= MAXV || v < 0 || v >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }
        adj[(int)u][(int)v] = 1;
    }
    for (int i = 0; i < MAXV && !found_cycle; ++i) {
        if (colour[i] == 0) dfs(i);
    }
    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
